const readEnv = (name) => {
  try {
    const v = process?.env?.[name];
    return typeof v === 'string' && v.trim() ? v.trim() : '';
  } catch { return ''; }
};
const bufferFolderId = readEnv('SIGA_TELEGRAM_BUFFER_FOLDER_ID') || '1tbyhFwLBWm5jh605vngOqpHN-Gpb-9yf';
const sharedSecret = readEnv('SIGA_WEBHOOK_SECRET') || readEnv('SIGA_SHARED_SECRET') || readEnv('N8N_SIGA_WEBHOOK_SECRET') || readEnv('N8N_SIGA_SHARED_SECRET') || '';
return [{ json: { now: new Date().toISOString(), buffer_folder_id: bufferFolderId, buffer_folder_path: 'SIGA_TEMP/SIGA_TELEGRAM_BUFFER', shared_secret: sharedSecret, quiet_window_sec_default: 5, processor_source: 'telegram_buffer_to_drive_brief', final_drive_root_id: '1e6OipL7R8HlG5LV1Lp8Z_AMlFQMTxaRC', min_message_received_at: '2026-05-31T07:06:52.8281810Z' } }];

const root = $('Init Processor Config').first().json || {};
const files = Array.isArray($json.files) ? [...$json.files] : [];
const partFiles = files.filter(f => /__part_\d+\.json$/i.test(String(f.name || '')));
return [{
  json: {
    ...root,
    part_json_files: partFiles,
    part_json_count: partFiles.length
  }
}];

const root = $json;
return root.part_json_files.map(f => ({
  json: { ...root, part_json_file_id: f.id, part_json_name: f.name }
}));

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let txt = '';
  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    txt = Buffer.from(buf).toString('utf8');
  } catch (e) { continue; }
  txt = String(txt || '').replace(/^\uFEFF/, '').trim();
  const parsed = JSON.parse(txt);
  out.push({
    json: {
      ...item.json,
      part: parsed,
      buffer_prefix: parsed.buffer_prefix || item.json.buffer_prefix || '',
      group_key: parsed.group_key || ''
    }
  });
}
return out;

const now = Date.now();
const minReceivedAt = Date.parse(($('Init Processor Config').first().json || {}).min_message_received_at || '') || 0;
const items = $input.all().map(i => i.json || {}).filter(j => {
  const p = j.part || j;
  const t = Date.parse(p.message_received_at || j.message_received_at || '') || 0;
  return !minReceivedAt || !t || t >= minReceivedAt;
});
const groups = new Map();

const firstNonEmpty = (arr, keys) => {
  for (const x of arr) {
    for(const key of keys) {
        const val = x[key] || x.part?.[key];
        if (val !== null && val !== undefined && val !== '') return val;
    }
  }
  return null;
};

for (const j of items) {
  const prefix = j.buffer_prefix || '';
  if (!prefix) continue;
  const g = groups.get(prefix) || { parts: [], root: j, lastQuietUntil: 0, firstSeen: Number.MAX_SAFE_INTEGER };
  const part = j.part || {};
  g.parts.push(part);
  const q = Date.parse(part.quiet_until || '') || 0;
  const seen = Date.parse(part.message_received_at || '') || now;
  if (q > g.lastQuietUntil) g.lastQuietUntil = q;
  if (seen < g.firstSeen) g.firstSeen = seen;
  if ((part.message_text || part.caption_text || part.text) && !(g.root.part?.message_text || g.root.part?.caption_text || g.root.part?.text)) g.root = j;
  groups.set(prefix, g);
}

const ready = [...groups.values()]
  .filter(g => g.lastQuietUntil > 0 && g.lastQuietUntil <= now)
  .sort((a, b) => a.firstSeen - b.firstSeen);

if (!ready.length) return [{ json: { ready_group_found: false, reason: 'no_ready_group' } }];

const g = ready[0];
const parts = [...g.parts].sort((a, b) => Number(a.message_id || 0) - Number(b.message_id || 0));
const markerName = `${g.root.buffer_prefix}processed.json`;

return [{
  json: {
    ...$('Init Processor Config').first().json,
    ready_group_found: true,
    buffer_prefix: g.root.buffer_prefix,
    group_key: g.root.group_key,
    media_group_id: firstNonEmpty(parts, ['media_group_id']),
    chat_id: firstNonEmpty(parts, ['chat_id']),
    chat_type: firstNonEmpty(parts, ['chat_type']),
    sender: firstNonEmpty(parts, ['sender']) || {},
    message_text: firstNonEmpty(parts, ['message_text', 'caption_text', 'text']) || '',
    quiet_until: new Date(g.lastQuietUntil).toISOString(),
    group_parts: parts,
    processed_marker_name: markerName
  }
}];

const marker = $json || {};
const root = $('If Ready Group Found').first().json || {};
return [{
  json: {
    ...root,
    processed_marker_found: Array.isArray(marker.files) && marker.files.length > 0
  }
}];

const root = $('If Not Processed').first().json;
const files = Array.isArray($json.files) ? $json.files : [];
const parts = Array.isArray(root.group_parts) ? root.group_parts : [];
const byName = new Map(files.map(f => [String(f.name || ''), f]));
const mediaItems = [];

for (const p of parts) {
  const name = p.buffer_file_name;
  if (!name) continue;
  const f = byName.get(String(name));
  if (!f) continue;
  mediaItems.push({
    ...root,
    part: p,
    drive_file_id: f.id,
    drive_file_name: f.name,
    computed_mime_type: f.mimeType || p.mime_type || 'application/octet-stream',
    media_order: Number(p.message_id || mediaItems.length + 1)
  });
}
return mediaItems;

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const p = item.json.part || {};
  const mime = String(item.json.computed_mime_type || item.binary?.data?.mimeType || 'application/octet-stream').toLowerCase();
  const isImg = mime.startsWith('image/');
  const bKey = isImg ? `image_upload${i}` : `document_upload${i}`;

  const row = {
    index: i + 1,
    order: item.json.media_order,
    filename: p.original_filename || item.json.drive_file_name,
    mime_type: mime,
    binary_key: bKey
  };

  out.push({
    json: {
      ...item.json,
      image_row: isImg ? row : null,
      document_row: !isImg ? row : null
    },
    binary: item.binary
  });
}
return out;

const items = $input.all();
if (!items.length) return [{ json: { payload_ready: false } }];

const root = items[0].json;
const sharedSecret = $('Init Processor Config').first().json.shared_secret || '';

const images = items.map(i => i.json.image_row).filter(Boolean).sort((a, b) => a.order - b.order);
const documents = items.map(i => i.json.document_row).filter(Boolean).sort((a, b) => a.order - b.order);

images.forEach((img, idx) => img.index = idx + 1);
documents.forEach((doc, idx) => doc.index = idx + 1);

const sender = root.sender || {};

const payload = {
  source: 'telegram_buffered',
  trigger_source: 'telegram_buffer_batch',
  project: 'SIGA',
  entity_type: 'equipment',
  message: {
    text: root.message_text || '',
    received_at: new Date().toISOString()
  },
  sender: {
    id: sender.id || null,
    display_name: sender.first_name || sender.username || sender.display_name || null
  },
  context: {
    telegram: {
      chat_id: root.chat_id ?? null,
      chat_type: root.chat_type ?? null,
      media_group_id: root.media_group_id || null,
      group_key: root.group_key || null,
      buffer_prefix: root.buffer_prefix || null
    }
  },
  images: images.map(img => ({ index: img.index, filename: img.filename, mime_type: img.mime_type, binary_key: img.binary_key })),
  documents: documents.map(doc => ({ index: doc.index, filename: doc.filename, mime_type: doc.mime_type, binary_key: doc.binary_key })),
  headers: {
    'x-siga-shared-secret': sharedSecret
  },
  processed_marker_name: root.processed_marker_name,
  buffer_folder_id: root.buffer_folder_id,
  group_key: root.group_key,
  buffer_prefix: root.buffer_prefix,
  payload_ready: true
};

const outBinary = {};
items.forEach((item) => {
  const row = item.json.image_row || item.json.document_row;
  if (row && item.binary && item.binary.data) {
    outBinary[row.binary_key] = item.binary.data;
    outBinary[row.binary_key].fileName = row.filename;
    outBinary[row.binary_key].mimeType = row.mime_type;
  }
});

return [{
  json: payload,
  binary: Object.keys(outBinary).length ? outBinary : undefined
}];

const markerName = String($json.marker_name || '');
const prefix = String($json.buffer_prefix || '');
const files = Array.isArray($json.files) ? $json.files : [];
const toDelete = files
  .filter(f => f.id && (!prefix || String(f.name || '').includes(prefix)))
  // Le marqueur est supprime en dernier: s'il y a une erreur avant, il reste et evite un retraitement.
  .sort((a, b) => {
    const am = markerName && a.name === markerName ? 1 : 0;
    const bm = markerName && b.name === markerName ? 1 : 0;
    return am - bm;
  });
return toDelete.map(f => ({ json: { file_id: f.id, file_name: f.name, marker_name: markerName, buffer_prefix: prefix } }));

function sanitize(value) {
  return String(value || '').normalize('NFKD').replace(/[^\x00-\x7F]/g, '').replace(/[^a-zA-Z0-9._-]+/g, '_').replace(/_+/g, '_').replace(/^_+|_+$/g, '').slice(0, 120) || 'brief';
}
function stampFromIso(iso) {
  const d = new Date(iso || Date.now());
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}${pad(d.getUTCMonth()+1)}${pad(d.getUTCDate())}-${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}`;
}
const payload = $json || {};
const selected = $('If Not Processed').first().json || {};
const parts = Array.isArray(selected.group_parts) ? [...selected.group_parts] : [];
parts.sort((a, b) => Number(a.message_id || 0) - Number(b.message_id || 0));
const firstPart = parts[0] || {};
const telegram = payload.context?.telegram || {};
const chatId = telegram.chat_id ?? selected.chat_id ?? null;
const mediaGroupId = telegram.media_group_id || selected.media_group_id || null;
const folderName = mediaGroupId ? `album_${sanitize(chatId)}_${sanitize(mediaGroupId)}` : `${stampFromIso(firstPart.message_received_at || payload.message?.received_at)}_msg${firstPart.message_id || 'unknown'}`;
return [{ json: { ...payload, group_parts: parts, brief_folder_name: folderName, brief_id: folderName, final_drive_root_id: $('Init Processor Config').first().json.final_drive_root_id }, binary: $input.first().binary }];

const ctx = $('Build Brief Folder Context').first().json;
const folder = $('Create Brief Drive Folder').first().json;
const payloadItem = $('Aggregate Final Payload').first();
const binary = payloadItem.binary || {};
const rows = [ ...((ctx.images || []).map(x => ({ ...x, kind: 'photo' }))), ...((ctx.documents || []).map(x => ({ ...x, kind: 'document' }))) ].sort((a, b) => Number(a.index || 0) - Number(b.index || 0));
const out = [];
for (const row of rows) {
  const b = binary[row.binary_key];
  if (!b) continue;
  const ext = String(row.filename || '').split('.').pop() || (row.kind === 'photo' ? 'jpg' : 'bin');
  const target = row.kind === 'photo' ? `photo_${String(row.index).padStart(2, '0')}.${ext}` : `document_${String(row.index).padStart(2, '0')}.${ext}`;
  out.push({ json: { brief_id: ctx.brief_id, brief_folder_id: folder.id, brief_folder_name: ctx.brief_folder_name, brief_folder_url: folder.webViewLink || `https://drive.google.com/drive/folders/${folder.id}`, target_filename: target, original_filename: row.filename || target, mime_type: row.mime_type || b.mimeType || 'application/octet-stream', kind: row.kind, index: row.index, telegram_message_id: (ctx.group_parts || [])[Number(row.index || 1) - 1]?.message_id || null }, binary: { data: { ...b, fileName: target, mimeType: row.mime_type || b.mimeType || 'application/octet-stream' } } });
}
return out;

const uploads = $input.all();
const split = $('Split Brief Upload Files').all();
const ctx = $('Build Brief Folder Context').first().json;
const folder = $('Create Brief Drive Folder').first().json;
const folderUrl = folder.webViewLink || `https://drive.google.com/drive/folders/${folder.id}`;
const photos = [];
const documents = [];
for (let i = 0; i < uploads.length; i++) {
  const u = uploads[i].json || {};
  const s = split[i]?.json || {};
  const row = { filename: s.target_filename || u.name || null, original_filename: s.original_filename || null, drive_file_id: u.id || null, mime: s.mime_type || u.mimeType || null, telegram_message_id: s.telegram_message_id || null };
  if (s.kind === 'document') documents.push(row); else photos.push(row);
}
const telegram = ctx.context?.telegram || {};
const brief = { brief_id: ctx.brief_id, created_at: new Date().toISOString(), source: 'telegram', status: 'pending', text: ctx.message?.text || '', photos, documents, drive: { folder_id: folder.id, folder_name: ctx.brief_folder_name, folder_url: folderUrl }, telegram: { chat_id: telegram.chat_id ?? null, chat_type: telegram.chat_type ?? null, media_group_id: telegram.media_group_id || null, group_key: telegram.group_key || ctx.group_key || null, buffer_prefix: telegram.buffer_prefix || ctx.buffer_prefix || null }, siga: { action: null, items: [], processed_at: null, notes: null } };
const txt = JSON.stringify(brief, null, 2);
return [{ json: { ...ctx, brief, brief_folder_id: folder.id, brief_folder_name: ctx.brief_folder_name, brief_folder_url: folderUrl, telegram_chat_id: telegram.chat_id ?? null }, binary: { data: { data: Buffer.from(txt, 'utf8').toString('base64'), mimeType: 'application/json', fileName: 'brief.json' } } }];

const ctx = $('Build Brief JSON').first().json;
const txt = JSON.stringify({ group_key: ctx.group_key, buffer_prefix: ctx.buffer_prefix, processed_at: new Date().toISOString(), status: 'brief_created', brief_folder_id: ctx.brief_folder_id, brief_folder_name: ctx.brief_folder_name, brief_folder_url: ctx.brief_folder_url, photo_count: ctx.brief?.photos?.length || 0, document_count: ctx.brief?.documents?.length || 0 }, null, 2);
return [{ json: { marker_name: ctx.processed_marker_name, buffer_folder_id: ctx.buffer_folder_id, buffer_prefix: ctx.buffer_prefix, brief_folder_id: ctx.brief_folder_id, brief_folder_url: ctx.brief_folder_url }, binary: { data: { data: Buffer.from(txt, 'utf8').toString('base64'), mimeType: 'application/json', fileName: ctx.processed_marker_name } } }];

let ctx = {};
try {
  ctx = $('Build Marker Binary').first().json || {};
} catch (e) {
  ctx = $input.first().json || {};
}
const markerName = ctx.marker_name || ctx.processed_marker_name || (ctx.buffer_prefix ? ctx.buffer_prefix + 'processed.json' : '');
const bufferFolderId = ctx.buffer_folder_id || $('Init Processor Config').first().json.buffer_folder_id;
const bufferPrefix = ctx.buffer_prefix || '';
if (!bufferFolderId || !bufferPrefix) {
  throw new Error('Missing cleanup context: buffer_folder_id or buffer_prefix');
}
return [{
  json: {
    buffer_folder_id: bufferFolderId,
    buffer_prefix: bufferPrefix,
    marker_name: markerName,
    cleanup_requested_at: new Date().toISOString()
  }
}];
